// ============================================
// VALIDATION INPUT - MCP Text Embedder
// RFC-014 Extraction with Optional Context Fields
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (extract for tracing, NO validation errors if missing) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required parameters specific to this webhook ---
const text = body.text || ctx.text;
const openaiApiKey = body.openai_api_key || ctx.openai_api_key;
const model = body.model || ctx.model || 'text-embedding-3-small';
const dimensions = body.dimensions || ctx.dimensions || 1536;

if (!text) {
  errors.push('text requis (string ou array de strings)');
}

if (!openaiApiKey) {
  errors.push('openai_api_key requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  text: text,
  openai_api_key: openaiApiKey,
  model: model,
  dimensions: dimensions,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'openai',
    model: 'text-embedding-3-small',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// PARSE RESPONSE - MCP Text Embedder
// With _trace for analyzable webhooks
// ============================================

const items = $input.all();
const validationData = $('Validate Input').first().json;

const results = items.map(item => {
  const latencyMs = Date.now() - validationData.startTime;

  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          model: validationData.model
        },
        user_id: validationData.user_id,
        guild_id: validationData.guild_id,
        user_request: validationData.user_request,
        _trace: {
          service_response: { error: item.json.error },
          provider: 'openai',
          model: validationData.model,
          mode: 'error',
          latency_ms: latencyMs,
          user_id: validationData.user_id,
          guild_id: validationData.guild_id,
          user_request: validationData.user_request
        }
      }
    };
  }

  try {
    const data = item.json.data || [];
    const embeddings = data.map(d => ({
      index: d.index,
      embedding: d.embedding,
      dimensions: d.embedding?.length || 0
    }));

    const responseData = {
      embeddings: embeddings,
      count: embeddings.length,
      model: item.json.model,
      dimensions: embeddings[0]?.dimensions || 0
    };

    return {
      json: {
        success: true,
        data: responseData,
        meta: {
          provider: 'openai',
          model: item.json.model || validationData.model,
          usage: item.json.usage || {}
        },
        user_id: validationData.user_id,
        guild_id: validationData.guild_id,
        user_request: validationData.user_request,
        _trace: {
          service_response: responseData,
          provider: 'openai',
          model: item.json.model || validationData.model,
          mode: 'success',
          latency_ms: latencyMs,
          token_usage: item.json.usage || {},
          user_id: validationData.user_id,
          guild_id: validationData.guild_id,
          user_request: validationData.user_request
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse embeddings response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          model: validationData.model
        },
        user_id: validationData.user_id,
        guild_id: validationData.guild_id,
        user_request: validationData.user_request,
        _trace: {
          service_response: { parse_error: e.message },
          provider: 'openai',
          model: validationData.model,
          mode: 'error',
          latency_ms: latencyMs,
          user_id: validationData.user_id,
          guild_id: validationData.guild_id,
          user_request: validationData.user_request
        }
      }
    };
  }
});

return results;
